     1	import { component$, useSignal, useVisibleTask$ } from "@qwik.dev/core";
     2	import { createAppError } from "../../utils/application-errors";
     3	import { ApplicationNotice } from "./application-notice";
     4	
     5	/**
     6	 * Application-wide connectivity banner. Inline notices remain the default for
     7	 * a single failed operation; this is reserved for the browser losing its
     8	 * network connection entirely, where every operation would fail. Local editing
     9	 * keeps working and unsynced work stays safe, so the copy reassures rather
    10	 * than blocks.
    11	 */
    12	export const GlobalConnectivityBanner = component$(() => {
    13	  const offline = useSignal(false);
    14	
    15	  // eslint-disable-next-line qwik/no-use-visible-task
    16	  useVisibleTask$(
    17	    ({ cleanup }) => {
    18	      if (typeof navigator === "undefined") return;
    19	      const sync = () => {
    20	        offline.value = navigator.onLine === false;
    21	      };
    22	      sync();
    23	      window.addEventListener("online", sync);
    24	      window.addEventListener("offline", sync);
    25	      cleanup(() => {
    26	        window.removeEventListener("online", sync);
    27	        window.removeEventListener("offline", sync);
    28	      });
    29	    },
    30	    { strategy: "document-ready" },
    31	  );
    32	
    33	  if (!offline.value) return null;
    34	
    35	  return (
    36	    <div class="sticky top-0 z-50 w-full">
    37	      <ApplicationNotice
    38	        variant="outage"
    39	        title="You are offline"
    40	        error={createAppError("NETWORK_UNAVAILABLE", {
    41	          source: "fetch",
    42	          recovery: { action: "check-connection", canRetry: false },
    43	          metadata: { operation: "connectivity" },
    44	        })}
    45	      />
    46	    </div>
    47	  );
    48	});

