     1	import { component$, isDev, useVisibleTask$ } from "@qwik.dev/core";
     2	import { RouterOutlet, useQwikRouter } from "@qwik.dev/router";
     3	import { RouterHead } from "./components/router-head/router-head";
     4	import { ConvexProvider } from "./utils/convex-context";
     5	import { AuthProvider } from "./utils/auth-context";
     6	import { PostHogProvider } from "./utils/posthog-context";
     7	import { installLixAuthInterceptor } from "./utils/lix-auth";
     8	import { GlobalConnectivityBanner } from "./components/ui/global-connectivity-banner";
     9	import { GlobalApplicationToasts } from "./components/ui/global-application-toasts";
    10	import { GlobalSpeechPlayer } from "./components/ui/global-speech-player";
    11	import { UsageSyncController } from "./components/desk/usage-sync-controller";
    12	import {
    13	  THEME_BOOTSTRAP_SCRIPT,
    14	  applyTheme,
    15	  readThemePreference,
    16	} from "./utils/theme";
    17	
    18	import "./global.css";
    19	
    20	const SERVICE_WORKER_REGISTER_SCRIPT = `
    21	if ("serviceWorker" in navigator) {
    22	  navigator.serviceWorker
    23	    .register(${JSON.stringify(`${import.meta.env.BASE_URL}service-worker.js`)})
    24	    .catch((error) => console.error("Twyne service worker registration failed", error));
    25	}
    26	`;
    27	
    28	export default component$(() => {
    29	  useQwikRouter({ viewTransition: true });
    30	
    31	  const convexUrl = (import.meta.env.PUBLIC_CONVEX_URL ??
    32	    import.meta.env.VITE_CONVEX_URL) as string | undefined;
    33	
    34	  // eslint-disable-next-line qwik/no-use-visible-task
    35	  useVisibleTask$(() => {
    36	    installLixAuthInterceptor();
    37	
    38	    // The bootstrap script resolves "System" once, at load. Keep following the
    39	    // OS afterwards, so flipping the machine to dark at dusk re-inks the room
    40	    // without a reload. Explicit presets are left alone.
    41	    const query = window.matchMedia("(prefers-color-scheme: dark)");
    42	    const sync = () => {
    43	      const preference = readThemePreference();
    44	      if (preference.preset !== "system") return;
    45	      applyTheme(preference, document.documentElement, query.matches);
    46	    };
    47	    query.addEventListener("change", sync);
    48	    return () => query.removeEventListener("change", sync);
    49	  });
    50	
    51	  return (
    52	    <>
    53	      <head>
    54	        <meta charset="utf-8" />
    55	        {/*
    56	          Stamps the writer's palette onto <html> before the first paint.
    57	          It has to be an inline script rather than a component: Qwik
    58	          server-renders the document, so any QRL resumes long after the
    59	          browser has already painted the default cream — which is exactly
    60	          the flash this avoids. The source lives in `utils/theme.ts` so it
    61	          cannot drift from `applyTheme`.
    62	        */}
    63	        <script
    64	          data-theme-bootstrap
    65	          dangerouslySetInnerHTML={THEME_BOOTSTRAP_SCRIPT}
    66	        />
    67	        {!isDev && (
    68	          <link
    69	            rel="manifest"
    70	            href={`${import.meta.env.BASE_URL}manifest.json`}
    71	          />
    72	        )}
    73	        {/* Editorial type stack — Libre Baskerville (display), Lora (body),
    74	            DM Sans (UI), Special Elite (typewriter). Fraunces remains loaded
    75	            for manuscripts that persisted the former display-font mark. */}
    76	        <link rel="preconnect" href="https://fonts.googleapis.com" />
    77	        <link
    78	          rel="preconnect"
    79	          href="https://fonts.gstatic.com"
    80	          crossOrigin="anonymous"
    81	        />
    82	        <link
    83	          rel="stylesheet"
    84	          href="https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600;9..40,700&family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&family=Libre+Baskerville:ital,wght@0,400;0,700;1,400&family=Lora:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Special+Elite&display=swap"
    85	        />
    86	        <RouterHead />
    87	      </head>
    88	      <body lang="en">
    89	        <GlobalConnectivityBanner />
    90	        <GlobalApplicationToasts />
    91	        <ConvexProvider url={convexUrl}>
    92	          <AuthProvider>
    93	            <PostHogProvider>
    94	              <UsageSyncController />
    95	              <RouterOutlet />
    96	              <GlobalSpeechPlayer />
    97	              {!isDev && (
    98	                <script
    99	                  type="module"
   100	                  dangerouslySetInnerHTML={SERVICE_WORKER_REGISTER_SCRIPT}
   101	                />
   102	              )}
   103	            </PostHogProvider>
   104	          </AuthProvider>
   105	        </ConvexProvider>
   106	      </body>
   107	    </>
   108	  );
   109	});

