     1	/**
     2	 * Sync indicator — a small dot in the editor toolbar plus a
     3	 * "last saved Xs ago" line in the colophon. Both are wired to
     4	 * the `twyne:sync-status` event that `convex-sync` fires when
     5	 * the underlying state changes. The component is pure with
     6	 * respect to the event stream: it doesn't import convex-sync
     7	 * or know how the status is derived.
     8	 */
     9	
    10	import type { SyncStatus } from "../../utils/convex-sync";
    11	
    12	/**
    13	 * Map a sync status to the colour the indicator dot should
    14	 * show. Vermilion is the danger colour (offline / error),
    15	 * paper-3 is the in-flight / pending state (deliberately
    16	 * quiet so it doesn't fight the cursor), and accent-green is
    17	 * the steady "you are saved" state.
    18	 */
    19	export function statusColor(status: SyncStatus): string {
    20	  switch (status.kind) {
    21	    case "offline":
    22	    case "error":
    23	      return "var(--color-vermilion)";
    24	    case "pending":
    25	    case "syncing":
    26	      return "var(--color-paper-3)";
    27	    case "synced":
    28	      return "var(--color-accent-green)";
    29	    case "local-only":
    30	      return "var(--color-ink-muted)";
    31	  }
    32	}
    33	
    34	/**
    35	 * Single-line human description shown in the dot's tooltip.
    36	 * Keeps the toolbar label short while the colophon line carries
    37	 * the timestamp.
    38	 */
    39	export function statusLabel(
    40	  status: SyncStatus,
    41	  now: number = Date.now(),
    42	): string {
    43	  switch (status.kind) {
    44	    case "local-only":
    45	      return "Local only — sign in to sync across devices";
    46	    case "offline":
    47	      return "Offline — your changes are still being saved locally";
    48	    case "pending":
    49	      return "Queued for sync…";
    50	    case "syncing":
    51	      return "Syncing…";
    52	    case "synced":
    53	      return `Synced ${formatAge(status.lastSyncedAt, now)}`;
    54	    case "error": {
    55	      const safetyCopy = /local work remains safe/i.test(status.message)
    56	        ? ""
    57	        : " Your local work remains safe on this device.";
    58	      return `Sync failed ${formatAge(status.lastErrorAt, now)} — ${status.message}${safetyCopy}`;
    59	    }
    60	  }
    61	}
    62	
    63	/**
    64	 * Format a timestamp as a human-friendly age: "12s ago",
    65	 * "3m ago", "2h ago", or "just now". Anything older than a
    66	 * day falls through to a date string so the tooltip doesn't
    67	 * grow without bound.
    68	 */
    69	export function formatAge(timestamp: number, now: number = Date.now()): string {
    70	  const seconds = Math.max(0, Math.floor((now - timestamp) / 1000));
    71	  if (seconds < 5) return "just now";
    72	  if (seconds < 60) return `${seconds}s ago`;
    73	  const minutes = Math.floor(seconds / 60);
    74	  if (minutes < 60) return `${minutes}m ago`;
    75	  const hours = Math.floor(minutes / 60);
    76	  if (hours < 24) return `${hours}h ago`;
    77	  return new Date(timestamp).toLocaleDateString();
    78	}
    79	
    80	/**
    81	 * The "last saved" line. Falls back to the current time when
    82	 * no successful save has happened yet, so the line never
    83	 * reads as empty.
    84	 */
    85	export function lastSavedLabel(
    86	  savedAt: number | null,
    87	  now: number = Date.now(),
    88	): string {
    89	  if (savedAt == null) return "Not saved yet";
    90	  return `Saved ${formatAge(savedAt, now)}`;

